1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
8	
9	/**
10	 * Rejects a create-owner request when an existing owner already has the same lastName and the same
11	 * address. Both fields are compared case-insensitively with surrounding and repeated internal
12	 * whitespace collapsed, so cosmetic differences do not hide a shared household. A request that opts
13	 * in with {@code sharesHousehold: true} bypasses the check. On a match it throws
14	 * {@link DuplicateHouseholdException}, handled globally as 409.
15	 */
16	public class EnsureHouseholdUnique {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String lastName = normalize(request.getLastName());
24	        String address = normalize(request.getAddress());
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (lastName.equals(normalize(existing.getLastName()))
27	                    && address.equals(normalize(existing.getAddress()))) {
28	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
29	            }
30	        }
31	    }
32	
33	    /** Lower-cased, trimmed, with runs of whitespace collapsed to a single space. */
34	    private static String normalize(String value) {
35	        if (value == null) {
36	            return "";
37	        }
38	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
39	    }
40	}
