1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
9	
10	/**
11	 * Runs after {@link ValidateOwnerFields} has normalized the telephone to E.164 form: rejects the
12	 * request when any existing owner already has the same E.164 telephone. Both sides are canonicalized
13	 * to E.164 before comparison so differing formats do not hide a duplicate. On a match it throws
14	 * {@link DuplicateTelephoneException}, handled globally as 409.
15	 */
16	public class EnsureTelephoneUnique {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateTelephoneException {
20	        String telephone = canonical(request.getTelephone());
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (telephone.equals(canonical(existing.getTelephone()))) {
23	                throw new DuplicateTelephoneException(request.getTelephone());
24	            }
25	        }
26	    }
27	
28	    /**
29	     * The E.164 form used for comparison. The request's telephone is already E.164; an existing
30	     * value that predates E.164 storage is normalized on the fly, falling back to its bare digits if
31	     * it cannot form valid E.164.
32	     */
33	    private static String canonical(String value) {
34	        try {
35	            return OwnerTelephone.toE164(value);
36	        } catch (InvalidTelephoneException ex) {
37	            return value == null ? "" : value.replaceAll("\\D", "");
38	        }
39	    }
40	}
