9	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
10	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
11	import org.springframework.web.bind.annotation.RequestBody;
12	
13	/**
14	 * First step of {@code POST /api/owners}: rejects a request that is missing or blank in any of
15	 * firstName, lastName, address, city or telephone. A whitespace-only value counts as blank, which
16	 * bean validation alone does not catch for the pattern-less address/city fields, so the check is
17	 * explicit here. The telephone is then normalized to E.164 form (see {@link OwnerTelephone}); the
18	 * normalized value is written back so it is stored and returned, and a value that cannot form valid
19	 * E.164 is a 400. The
20	 * optional email, when present, must be a syntactically valid address and is normalized to lower
21	 * case; a present-but-invalid email is a 400. On success it republishes the body for {@link BuildOwner}.
22	 */
23	public class ValidateOwnerFields {
24	
25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
26	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
27	        List<String> missing = new ArrayList<>();
28	        require("firstName", request.getFirstName(), missing);
29	        require("lastName", request.getLastName(), missing);
30	        require("address", request.getAddress(), missing);
31	        require("city", request.getCity(), missing);
32	        require("telephone", request.getTelephone(), missing);
33	        if (!missing.isEmpty()) {
34	            throw new MissingOwnerFieldsException(missing);
35	        }
36	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
37	        request.setEmail(OwnerEmail.normalize(request.getEmail()));
38	        validated.set(request);
39	    }
40	
41	    private static void require(String field, String value, List<String> missing) {
42	        if (value == null || value.isBlank()) {
43	            missing.add(field);
44	        }
45	    }
46	}
